private val routes = AtomicReference(persistentMapOf<String, Int>())

fun lookup(key: String): Int? = routes.get()[key]     // lock-free read

fun add(key: String, value: Int) {
    routes.updateAndGet { current ->                  // CAS retry loop
        current.put(key, value)                       // new persistent map, shares structure
    }
}
